import * as THREE from './vendor/three.module.js';
import {createWorld} from './world.js';
import {createTimeOfDay} from './lighting.js';
const $=id=>document.getElementById(id);
const scene=new THREE.Scene();scene.background=new THREE.Color('#c0d3cc');scene.fog=new THREE.Fog('#c0d3cc',55,125);
let renderer;try{renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});}catch(e){$('loading').textContent='This game needs a browser with WebGL enabled.';throw e;}
renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;renderer.setClearColor('#c0d3cc');$('world').appendChild(renderer.domElement);
const camera=new THREE.PerspectiveCamera(45,innerWidth/innerHeight,.1,180);const ambient=new THREE.HemisphereLight('#fff5d8','#647e60',1.65);scene.add(ambient);const sun=new THREE.DirectionalLight('#fff0da',2.3);sun.position.set(-18,28,12);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-40,right:40,top:40,bottom:-40,near:.5,far:110});sun.shadow.bias=-.0002;sun.shadow.normalBias=.025;sun.shadow.radius=3;scene.add(sun);
const {cat,body,head,legs,tail,fish,houses,colliders,laundry,updateEnvironment,life,nature}=createWorld(scene);
const timeOfDay=createTimeOfDay(scene,renderer,sun,ambient);
let started=false,muted=true,audioCtx,vertical=0,height=0,yaw=.15,zoom=13,elapsed=0,toastTimer;const keys=new Set();
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2800);}
function start(){started=true;document.body.classList.add('playing');$('intro').classList.add('hidden');}
function tone(freq,duration=.2){if(muted)return;audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.setValueAtTime(freq,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.6,audioCtx.currentTime+duration);g.gain.setValueAtTime(.09,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}
function jump(){start();if(height<=.001){vertical=5.2;tone(440,.12);}}
let meowUntil=0;function meow(){start();meowUntil=elapsed+.65;toast(nature.reactToMeow()||life.reactToMeow()||'Meow! Selamat petang, kampung.');tone(720,.45);}
$('play').onclick=()=>{start();toast('Meet your neighbors — meow nearby to say hello!');};$('help').onclick=()=>{$('helpDialog').showModal();keys.clear();};$('closeHelp').onclick=()=>$('helpDialog').close();$('helpPlay').onclick=()=>{$('helpDialog').close();start();};$('sound').onclick=()=>{muted=!muted;$('sound').textContent=muted?'♫':'♪';$('sound').setAttribute('aria-label',muted?'Enable sound':'Mute sound');if(!muted)tone(640);toast(muted?'Sound off':'Sound on — try a meow!');};$('reset').onclick=()=>{cat.position.set(0,0,17);height=0;vertical=0;yaw=.15;zoom=13;toast('Back at the village entrance.');};$('touchJump').onclick=jump;$('touchMeow').onclick=meow;
function chooseTime(mode){
  timeOfDay.setMode(mode);
  $('day').setAttribute('aria-pressed',String(mode==='day'));
  $('evening').setAttribute('aria-pressed',String(mode==='evening'));
  $('weather').textContent=mode==='evening'?'◒  Sunset in the kampung':'☀  A lively afternoon';
  document.body.dataset.time=mode;
}
$('day').onclick=()=>chooseTime('day');
$('evening').onclick=()=>chooseTime('evening');
const keymap={arrowup:'w',arrowdown:'s',arrowleft:'a',arrowright:'d'};
window.addEventListener('keydown',e=>{if($('helpDialog').open)return;let k=e.key.toLowerCase();k=keymap[k]||k;if(['w','a','s','d',' ','shift','e'].includes(k)){e.preventDefault();if(!e.repeat&&k===' ')jump();if(!e.repeat&&k==='e')meow();keys.add(k);start();}});window.addEventListener('keyup',e=>{let k=e.key.toLowerCase();keys.delete(keymap[k]||k);});window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>keys.clear());
for(let b of document.querySelectorAll('[data-move]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.move);start();};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.move);}
let dragging=false,lastX;renderer.domElement.addEventListener('pointerdown',e=>{dragging=true;lastX=e.clientX;renderer.domElement.setPointerCapture(e.pointerId);});renderer.domElement.addEventListener('pointermove',e=>{if(dragging){yaw-=(e.clientX-lastX)*.006;lastX=e.clientX;}});renderer.domElement.addEventListener('pointerup',()=>dragging=false);renderer.domElement.addEventListener('pointercancel',()=>dragging=false);renderer.domElement.style.touchAction='none';renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();zoom=THREE.MathUtils.clamp(zoom+e.deltaY*.015,7,22);},{passive:false});
const map=$('minimap').getContext('2d');function drawMap(){map.clearRect(0,0,160,160);map.save();map.translate(80,80);map.beginPath();map.arc(0,0,69,0,Math.PI*2);map.clip();map.fillStyle='#9daf7d';map.fillRect(-80,-80,160,160);map.fillStyle='#d8c395';map.fillRect(-7,-80,14,160);map.fillRect(-80,10,160,9);map.fillStyle='#84b1a6';map.fillRect(49,-80,14,160);map.fillStyle='#76a69a';map.beginPath();map.ellipse(nature.pond.x*1.9,nature.pond.z*1.6,nature.pond.rx*1.9,nature.pond.rz*1.6,0,0,Math.PI*2);map.fill();for(let h of houses){map.fillStyle='#e9d6a5';map.fillRect(h.x*1.9-h.w,h.z*1.6-h.d,h.w*2,h.d*2);map.fillStyle='#9b654a';map.fillRect(h.x*1.9-h.w,h.z*1.6-h.d,h.w*2,3);}for(let f of fish)if(!f.collected){map.fillStyle='#ffe7a1';map.beginPath();map.arc(f.x*1.9,f.z*1.6,2.5,0,Math.PI*2);map.fill();}for(const actor of [...life.villagers,...life.cats]){map.fillStyle=actor.kind==='cat'?'#efc38c':'#669888';map.beginPath();map.arc(actor.root.position.x*1.9,actor.root.position.z*1.6,actor.kind==='cat'?1.7:2.2,0,Math.PI*2);map.fill();}map.translate(cat.position.x*1.9,cat.position.z*1.6);map.rotate(-cat.rotation.y);map.fillStyle='#fff6dc';map.beginPath();map.moveTo(0,6);map.lineTo(-4,-4);map.lineTo(4,-4);map.closePath();map.fill();map.restore();}
const clock=new THREE.Clock(),target=new THREE.Vector3(),desired=new THREE.Vector3();let collected=0;function animate(){requestAnimationFrame(animate);let dt=Math.min(clock.getDelta(),.05);elapsed+=dt;const forward=(keys.has('w')?1:0)-(keys.has('s')?1:0),right=(keys.has('d')?1:0)-(keys.has('a')?1:0);let moving=started&&(forward||right)&&!$('helpDialog').open;
if(moving){let dx=right*Math.cos(yaw)-forward*Math.sin(yaw),dz=-right*Math.sin(yaw)-forward*Math.cos(yaw),len=Math.hypot(dx,dz);dx/=len;dz/=len;let speed=keys.has('shift')?6.4:3.3;function allowed(x,z){return x>-23&&x<23&&z>-39&&z<37&&!colliders.some(c=>{if(c.kind==='pond')return ((x-c.x)/(c.rx+.3))**2+((z-c.z)/(c.rz+.3))**2<1;if(!c.w)return Math.hypot(x-c.x,z-c.z)<c.r+.25;const dx=x-c.x,dz=z-c.z,localX=dx*Math.cos(c.rotation)-dz*Math.sin(c.rotation),localZ=dx*Math.sin(c.rotation)+dz*Math.cos(c.rotation);return Math.abs(localX)<c.w/2+.3&&Math.abs(localZ)<c.d/2+.3;});}let x=cat.position.x+dx*speed*dt,z=cat.position.z+dz*speed*dt;if(allowed(x,cat.position.z))cat.position.x=x;if(allowed(cat.position.x,z))cat.position.z=z;let angle=Math.atan2(dx,dz);cat.rotation.y+=Math.atan2(Math.sin(angle-cat.rotation.y),Math.cos(angle-cat.rotation.y))*Math.min(dt*14,1);}
vertical-=13*dt;height=Math.max(0,height+vertical*dt);if(height===0)vertical=0;cat.position.y=height;legs.forEach((l,i)=>l.rotation.x=moving?Math.sin(elapsed*(keys.has('shift')?18:11)+(i===0||i===3?0:Math.PI))*.55:Math.sin(elapsed*2)*.03);body.position.y=.64+(moving?Math.sin(elapsed*22)*.025:Math.sin(elapsed*2)*.012);tail.rotation.z=Math.sin(elapsed*3)*.2;head.rotation.x=elapsed<meowUntil?-.2:Math.sin(elapsed*1.8)*.025;laundry.forEach((m,i)=>m.rotation.x=Math.sin(elapsed*1.3+i)*.04);updateEnvironment(elapsed,height);life.update(elapsed,dt);nature.update(elapsed,dt,life.cats);
fish.forEach((f,i)=>{if(f.collected)return;f.g.position.y=.85+Math.sin(elapsed*2+i)*.13;f.g.rotation.y=elapsed*.8+i;if(started&&Math.hypot(cat.position.x-f.x,cat.position.z-f.z)<1){f.collected=true;scene.remove(f.g);collected++;$('count').textContent=`${collected} / 6`;$('progress').style.width=`${collected/6*100}%`;tone(950,.25);toast(collected===6?'All six fish! Oyen is the happiest cat in the kampung.':`A tasty find! ${collected} of 6 fish collected.`);if(collected===6){$('questTitle').textContent='A very happy kampung cat.';$('questText').textContent='All fish found. Stay a while and explore.';}}});
target.set(cat.position.x,cat.position.y+.8,cat.position.z);desired.set(target.x+Math.sin(yaw)*zoom,target.y+zoom*.57,target.z+Math.cos(yaw)*zoom);if(!started){desired.set(26,22,34);target.set(0,1,2);}camera.position.lerp(desired,1-Math.exp(-4*dt));camera.lookAt(target);drawMap();timeOfDay.update(dt,camera);renderer.render(scene,camera);}
camera.position.set(26,22,34);window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});$('loading').remove();animate();
